#!/usr/bin/env python3
"""Generate static HTML and coverage docs; no runtime/build dependency on the host."""
from pathlib import Path
from html import escape as e
from content import SECTIONS, GLOSSARY, SOURCES
import json, re
ROOT=Path(__file__).resolve().parents[1]
def paragraphs(text):
    return ''.join('<p>'+e(p)+'</p>' for p in text.split('\n\n'))
def table(headers,rows,caption):
    return '<div class="table-wrap"><table><caption>'+e(caption)+'</caption><thead><tr>'+''.join('<th scope="col">'+e(x)+'</th>' for x in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+e(x)+'</td>' for x in row)+'</tr>' for row in rows)+'</tbody></table></div>'
TABLES={
'foundations':table(['Layer','Main responsibility','Example output'],[['Bronze','Retain source + audit context','Raw event envelope'],['Silver','Validate and apply entity/history rules','Typed current orders or event history'],['Gold','Define business grain and metrics','Daily revenue by store']],'Medallion layers at a glance'),
'cdc-scd':table(['SCD type','After city changes A → B','Historical reporting'],[['0','Keep A','Original value only'],['1','Replace A with B','Current value only'],['2','Close A row; insert B row','Full versions if correctly modeled'],['3','current=B; previous=A','Limited prior attributes'],['4 (Kimball)','Separate rapid-change profile dimension','Profile referenced by fact'],['5','Type 4 + current profile reference','Historical profile + current lookup'],['6','Versioned rows + current attributes','Historical and current views'],['7','Durable key + historical surrogate paths','Two explicit reporting paths']],'SCD comparison — describe the structure because naming conventions vary'),
'retail':table(['Component','Inspected repository','Requested alternative'],[['Table format','Iceberg','Delta Lake'],['Storage','MinIO','MinIO'],['Catalog','Iceberg-oriented configuration','Open-source Unity Catalog'],['Compute/orchestration','Spark + Airflow','Spark + Airflow'],['Serving','PostgreSQL + FastAPI + React','Same serving pattern'],['Evidence','Public code inspected','Proposed design; not a completed migration']],'RetailPulse implementation and requested adaptation'),
'healthcare':table(['Entity','Merge key','Inspected policy'],[['patients','Id','Update + insert'],['medications','PATIENT + START + CODE','Update + insert'],['conditions','PATIENT + START + CODE','Update + insert'],['encounters','Id','Insert if missing'],['observations','PATIENT + DATE + CODE','Insert if missing']],'Healthcare Silver behavior from the inspected script'),
'production':table(['Failure point','Risk','Recovery design'],[['Before output commit','No durable output yet','Retry same bounded input'],['After commit, before progress checkpoint','Replay / duplicate effects','Idempotent key/version handling'],['After only some marts publish','Mixed versions visible','Staging + completed-version switch'],['Source retention expired','Cannot replay broker alone','Retained raw copy or re-extraction']],'Think through crash boundaries before release'),
}
nav=''.join(f'<a href="#{s["id"]}"><span>{i:02d}</span>{e(s["title"])}</a>' for i,s in enumerate(SECTIONS,1))
count=sum(len(s['cards']) for s in SECTIONS)
content=[]; coverage=[]; manifest=[]
for n,s in enumerate(SECTIONS,1):
    flow=''
    if s['flow']:
        flow='<div class="flow-label">Architecture / data flow</div><ol class="flow" aria-label="'+e(s['title'])+' data flow">'+''.join('<li>'+e(x)+'</li>' for x in s['flow'])+'</ol>'
    cards=[]
    for i,c in enumerate(s['cards'],1):
        cid=f'{s["id"]}-q{i}'
        badge=c['evidence']; cls='practice' if badge in ('Practice example','Proposed design') else 'evidence'
        code=''
        if c['code']:
            code='<div class="codebox"><div class="codebar"><span>Generic example · prerequisites in the answer</span><button type="button" class="copy" data-copy="'+cid+'-code">Copy code</button></div><pre><code id="'+cid+'-code">'+e(c['code'])+'</code></pre></div>'
            if c['output']: code+='<div class="output"><strong>Expected result</strong><pre>'+e(c['output'])+'</pre></div>'
        cards.append(f'''<details class="qa" id="{cid}" {'open' if i==1 else ''}><summary><span class="q-number">{i:02d}</span><span>{e(c['title'])}</span><span class="toggle" aria-hidden="true">+</span></summary><div class="answer"><span class="badge {cls}">{e(badge)}</span><h3>Understand it</h3>{paragraphs(c['plain'])}<div class="example"><strong>Simple example</strong>{paragraphs(c['example'])}</div>{code}<div class="spoken"><h3>Short interview answer</h3>{paragraphs(c['short'])}</div><h3>Detailed explanation</h3>{paragraphs(c['detailed'])}<h3>Likely follow-up</h3>{paragraphs(c['follow'])}<div class="mistake"><strong>Common mistake</strong>{paragraphs(c['mistake'])}</div><a class="permalink" href="#{cid}">Link to this answer <span aria-hidden="true">↗</span></a></div></details>''')
        coverage.append(f'- [x] [{c["title"]}](../index.html#{cid}) — {badge}')
        manifest.append(dict(id=cid,section=s['id'],title=c['title'],evidence=badge,code=bool(c['code'])))
    content.append(f'''<section class="chapter" id="{s['id']}" aria-labelledby="{s['id']}-title"><div class="chapter-heading"><p class="eyebrow">CHAPTER {n:02d} <span> / {len(s['cards'])} answers</span></p><h2 id="{s['id']}-title">{e(s['title'])}</h2><p class="chapter-intro">{e(s['intro'])}</p></div>{flow}{TABLES.get(s['id'],'')}<div class="questions">{''.join(cards)}</div></section>''')
    coverage.insert(len(coverage)-len(s['cards']), '\n## '+s['title']+'\n')
glossary=''.join(f'<div><dt>{e(k)}</dt><dd>{e(v)}</dd></div>' for k,v in sorted(GLOSSARY.items()))
refs=''.join(f'<li><a href="{e(url)}" target="_blank" rel="noopener noreferrer">{e(title)} <span aria-hidden="true">↗</span></a><span>{e(desc)}</span></li>' for title,url,desc in SOURCES)
html=f'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="Kirthik’s complete interview study guide: resume, three data projects, SQL, Python, Spark, CDC, SCD, production and MLOps Q&A."><meta name="theme-color" content="#164b45"><title>Kirthik’s Field Notes — Data Engineering Interview Guide</title><link rel="icon" href="./favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="./styles.css"><script src="./app.js" defer></script></head>
<body><a class="skip" href="#main">Skip to study content</a><header class="topbar"><a class="brand" href="#top"><span class="brand-icon" aria-hidden="true">k.</span><span>FIELD NOTES<small>Kirthik’s interview handbook</small></span></a><div class="top-actions"><span class="edition">DATA ENGINEERING / 01</span><button id="print" class="quiet" type="button">Print / Save PDF</button></div></header>
<div class="layout"><aside class="sidebar" aria-label="Study navigation"><p class="nav-label">THE STUDY MAP</p><nav>{nav}<a href="#glossary"><span>↳</span>Glossary</a><a href="#sources"><span>↳</span>Sources & evidence</a></nav><div class="sidebar-note"><span class="dot"></span><p>Learn the mechanism.<br>Then tell the story.</p></div></aside>
<main id="main"><div id="top" class="hero"><div class="hero-copy"><p class="eyebrow">YOUR EXPERIENCE, MADE UNDERSTANDABLE</p><h1>Know the data.<br><em>Own the conversation.</em></h1><p class="hero-description">From “I forgot the basics” to explaining the whole pipeline. A practical guide to your resume, projects, and the questions behind them.</p><div class="hero-links"><a class="primary" href="#resume">Start with your story <span aria-hidden="true">↗</span></a><a href="#revision">Quick revision →</a></div></div><div class="hero-note"><span class="note-index">FIELD GUIDE / 01</span><div class="mini-pipeline" aria-hidden="true"><span>raw</span><i>↓</i><span>refined</span><i>↓</i><span>ready.</span></div><p>Every layer.<br>Every decision.<br>One clear explanation.</p></div></div>
<div class="stats"><div><strong>{len(SECTIONS):02d}</strong><span>focused chapters</span></div><div><strong>{count}</strong><span>explained questions</span></div><div><strong>03</strong><span>personal projects</span></div><div><strong>{sum(bool(c['code']) for s in SECTIONS for c in s['cards']):02d}</strong><span>generic code examples</span></div></div>
<div class="study-start"><div><h2>Read it. Explain it. Test yourself.</h2><p>Open a question for the plain explanation, a simple example, an interview answer, follow-ups, and common mistakes. Code examples state their assumptions; Spark, dbt, MLflow, and API snippets need their respective environments.</p></div><div class="legend"><span class="badge evidence">Resume / repository evidence</span><span class="badge evidence">User-described experience</span><span class="badge practice">Proposed design / practice</span></div></div>
<div class="toolbar" id="study-tools"><div class="search-wrap"><label for="search">Find a topic or question</label><div class="search-input"><span aria-hidden="true">⌕</span><input id="search" type="search" placeholder="Try: SCD, checkpoint, SQL, MLflow…" autocomplete="off"><button type="button" id="clear-search" aria-label="Clear search" hidden>×</button></div></div><div class="tool-buttons"><button type="button" id="expand">Expand all</button><button type="button" id="collapse">Collapse all</button></div><p id="results" role="status" aria-live="polite">{count} questions · choose a chapter or search</p></div>
<noscript><p class="notice">All lessons work without JavaScript. Use the chapter links and open questions directly. Search, copy buttons, and expand-all require JavaScript.</p></noscript><p class="notice no-results" id="no-results" hidden>No matching questions. Try a broader term or clear the search.</p>
{''.join(content)}
<section id="glossary" class="chapter" aria-labelledby="glossary-title"><div class="chapter-heading"><p class="eyebrow">KEEP THIS NEARBY</p><h2 id="glossary-title">The plain-English glossary</h2><p class="chapter-intro">A quick lookup for the language behind the diagrams.</p></div><dl class="glossary">{glossary}</dl></section>
<section id="sources" class="chapter" aria-labelledby="sources-title"><div class="chapter-heading"><p class="eyebrow">FOLLOW THE EVIDENCE</p><h2 id="sources-title">Sources & how to use this guide</h2></div><div class="source-note"><p>The supplied resume and project inspections anchor the experience explanations. Additional forecasting work comes from your own description. Generic code, practice incidents, example numbers, and proposed designs are teaching material.</p><p>This guide preserves corrections rather than repeating unsupported implementation claims. The Healthcare baseline/recovery gaps, RetailPulse Iceberg implementation, local Delta + OSS Unity Catalog proposal, and Olist grain risks are intentional parts of the study material.</p><p>Original private employer code, Naukri profile contents, measurement logs, and precise model settings were not available. Personal contact details and credentials are excluded. Content assembled 15 November 2026; software capabilities depend on the release you use.</p></div><ul class="sources">{refs}</ul><p class="coverage-link"><a href="./docs/coverage.md">View the complete content coverage checklist ↗</a></p></section>
<footer><a class="brand" href="#top"><span class="brand-icon" aria-hidden="true">k.</span><span>KEEP LEARNING.<small>Build understanding, one question at a time.</small></span></a><a href="#top">Back to top ↑</a></footer></main></div><div id="toast" class="toast" role="status" aria-live="polite"></div></body></html>'''
(ROOT/'index.html').write_text(html)
(ROOT/'docs'/'coverage.md').write_text('# Content coverage checklist\n\n'+f'{count} questions across {len(SECTIONS)} chapters. Every answer contains explanation, example, short answer, detailed answer, follow-up, and mistake.\n\n'+ '\n'.join(coverage)+'''\n\n## Coverage and accuracy policy\n\n- [x] Resume summary, technical skills, four YLogx bullets, NIT internship, three projects, education and training.\n- [x] User-described retail demand/inventory, financial flow forecasting and MLflow work.\n- [x] Generic code examples, expected outputs and prerequisite notes.\n- [x] CDC methods and event/log distinction; SCD 0–7 with naming caveat and history examples.\n- [x] Production release, replay, backfill, skew, late data, schema drift, partial publication and recovery.\n- [x] RAG, LangChain, LangGraph, Chroma, GraphDB/MCP, MongoDB, APIs and SQL review.\n- [x] Prior corrections: Healthcare incomplete baseline, no verified durable recovery, ordinary batch Gold, resume-only infrastructure claims; RetailPulse actual Iceberg versus proposed Delta/OSS catalog, grain and monitoring gaps; Olist counts, join multiplication, metric and performance caveats.\n- [x] Glossary, architecture flows, comparison tables and revision guide.\n- [x] Public content excludes contact details, private source data and credentials.\n\nThis checklist maps all distinct substantive topics available from the conversation and supplied resume. It is an organized reconstruction, not a verbatim transcript or recovery of unavailable employer implementation details.\n''')
(ROOT/'docs'/'content-manifest.json').write_text(json.dumps(manifest,indent=2))
print(f'Built {count} Q&A, {len(SECTIONS)} chapters, {len(GLOSSARY)} glossary terms; {len(html.split())} HTML words.')
